<div class="card" style="margin-bottom:18px"><div class="section-head"><div><h2 class="section-title">Product comparison</h2><div class="section-meta">Total confirmed quantity received vs issued.</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Category</th><th>Unit</th><th>Variants</th><th>Total IN</th><th>Total OUT</th><th>Net</th></tr></thead><tbody><?php if(!$productRows): ?><tr><td colspan="7"><div class="empty"><strong>No movement found</strong>Try a wider date or category filter.</div></td></tr><?php else: foreach($productRows as $r): ?><tr><td><strong><?=esc($r['name'])?></strong><div class="muted mono"><?=esc($r['code'])?></div></td><td><?=esc($r['category_name']??'Uncategorized')?></td><td><?=esc($r['unit']??'')?></td><td><div class="variant-list"><?php foreach(($variantRowsByProduct[(int)$r['product_id']]??[]) as $vr): ?><span class="variant-chip"><?=esc(inventory_variant_attributes_label($vr['attributes_json'] ?? null, (string)$vr['variant_name']))?> <b>IN <?=number_format((int)$vr['total_in'])?></b> · <b>OUT <?=number_format((int)$vr['total_out'])?></b></span><?php endforeach; ?></div></td><td><span class="badge success">+<?=number_format((int)$r['total_in'])?> units</span></td><td><span class="badge danger">−<?=number_format((int)$r['total_out'])?> units</span></td><td><strong><?=number_format((int)$r['net'])?></strong></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
<div class="grid grid-2" style="margin-bottom:18px"><div class="card"><div class="section-head"><div><h2 class="section-title">Category comparison</h2><div class="section-meta">Aggregate movement by category and product unit; different units are never added together.</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Category</th><th>Unit</th><th>IN</th><th>OUT</th><th>Net</th></tr></thead><tbody><?php foreach($categoryRows as $r): ?><tr><td><strong><?=esc($r['category_name'])?></strong></td><td><?=esc($r['unit']??'')?></td><td><?=number_format((int)$r['total_in'])?></td><td><?=number_format((int)$r['total_out'])?></td><td><?=number_format((int)$r['net'])?></td></tr><?php endforeach; if(!$categoryRows): ?><tr><td colspan="5"><div class="empty">No category movement found.</div></td></tr><?php endif; ?></tbody></table></div></div>
<div class="card"><div class="section-head"><div><h2 class="section-title">Security Guard comparison</h2><div class="section-meta">Incoming quantity attributed from the registered incoming document. Split by product unit so pcs/kg/metres are not added together.</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Guard</th><th>Unit</th><th>IN quantity</th><th>Incoming transactions</th></tr></thead><tbody><?php foreach($guardRows as $r): ?><tr><td><strong><?=esc($r['guard_name']??'Unknown')?></strong></td><td><?=esc($r['unit']??'')?></td><td><span class="badge success">+<?=number_format((int)$r['total_in'])?> units</span></td><td><?=number_format((int)$r['incoming_transactions'])?></td></tr><?php endforeach; if(!$guardRows): ?><tr><td colspan="4"><div class="empty">No security-attributed incoming found.</div></td></tr><?php endif; ?></tbody></table></div></div></div>
